SELECT rv.id, rv.mascota_id, rv.vacuna_id, rv.fecha_aplicacion, rv.fecha_vencimiento, rv.lote, rv.veterinario, rv.observaciones, rv.created_at, rv.updated_at, rv.deleted, rv.version FROM petcare.registro_vacunacion rv
rv.deleted = FALSE AND rv.mascota_id = #{mascotaId}
ORDER BY rv.fecha_aplicacion DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM petcare.registro_vacunacion rv

    rv.deleted = FALSE
    AND rv.mascota_id = #{mascotaId}
